--도시와 유령--
UPDATE book
SET b_content =
        TO_CLOB(q'~어슴푸레한 저녁 몇 리를 걸어도 사람의 그림자 하나 찾아볼 수 없는 무인지경인 산골ᄍᆞᆨ 비탈길 여우의 밥이 다 되어 버린 해골덩이가 똘똘구는 무덤 옆 혹은 비가 축축히 뿌리는 버덩의 다 쓰러져 가는 물레방앗간, 또 혹은 몇 백 년이다 묵은 듯한 우중충한 늪가!
  거기에는 흔히 도깨비나 귀신이 나타난다 한다. 그럴 것이다. 고요하고 축축하고 우중충하고. 그리고 그것이 정칙일 것이다. 그러나 나는 아직도 그런 곳에서 그런 것을 본 적은 없다. 따라서 그런 것에 관하여서는 아무 지식도 가지지 못하였다. 하나 나는――자랑이 아니라―― 더 놀라운 유령을 보았다. 그리고 그것이 적어도 문명의 도시인 서울이니 놀라웁단 말이다. 나는 그래도 문명을 자랑하는 서울에서 유령을 목격하였다. 거짓말이라구? 아니다. 거짓말도 아니고 환영도 아니었다. 세상 사람이 말하여 ‘유령’이라는 것을 나는 이 두 분을 가지고 확실히 보았다.
  어떻든 길게 말할 것 없이 다음 이야기를 읽으면 알 것이다.
  동대문 밖에 상업학교가 가제될 무렵이었다. 나는 날마다 학교 집터에   ‘미쟁이’로 다니면서 일을 하였다. 남과 같이 버젓하게 일정한 노동을 못하고 밤낮 뜨내기 벌잇군으로밖에는 돌아다니지 못하는 나에게는 그래도 몇 달 동안은 입에 풀칠을 할 수 있었다. 마는 과격한 노동이었다. 그러므로 하루라도 쉬어본 일은커녕 한 번이라도 늦게 가존 적도 없었다. 원수같이 지글지글 타 내리는 여름 태양 아래에서 이른 아침부터 저녁때까지 감독의 말 한마디 거슬리는 법 없이 고분고분히 일을 하였다. 체로 모래를 쳐라, 불같은 태양 아래에 새까맣게 타는 석탄으로 ‘노리’를 끓여라, 시멘트에다 모래를 섞어라, 그것을 노리로 반죽하여라 하여 쉴 새 없는 기계같이 휘돌아쳤다. 그 열매인지 선물인지는 알 수 없으나 우리들이 다지는 시멘트가 ~') ||
        TO_CLOB(q'~몇 백 간의 벌집 같은 방으로 변하고 친구들의 쨍쨍 울리는 끌 소리가 여러 층의 웅장한 건축으로 변함을 볼 때에 미상불 우리의 위해단 힘을 또 한번 자랑하지 않을 수 없었다. ――어리석은 미련둥이들이라……(1행 약)……. 어떻든 콧구명이 다 턱턱 막히는 시멘트 가루를 전신에 보얗게 뒤집어쓰고 매캐한 노린 냄새와 더구나 전신을 한바탕 쪽 씻어 내리는 땀 냄새를 맡으면서 온종일 들볶에치고 나면 저녁물에는 정말이지 전신이 나른하였다. 그래도 집안 식구들을 생각하고 끼니거리를 생각하면 마지막 힘이 났다. 일을 마치고 정신을 가다듬어 가지고 일인 감독의 집으로 간다. 삯전을 얻어 가지고 그 길로 바로 술집에 가서 한잔 빨고 나면 그제야 겨우 제 세상인 듯싶었던 것이다.
  술! 사실 술처럼 고마운 것은 없었다. 버쩍버쩍 상하는 속, 말할 수 없는 피로를 잠시라도 잊게 하는 것은 그래도 술의 힘이었다.
  그날도 나는 술김에 얼근하였었다. 다른 때와 같이 역시 맨꽁무니에 떨어진 김서방과 나는 삯전을 받아들고 나서자마자 행길 옆 술집에서 만판 먹어댔다.
  술집을 나와 보니 벌써 밤은 꽤 저물었었다. 잠을 자도 한잠 너그러지게 잤을 판이었다. 잠이라니 말이지 종일 피곤하였던 판에 주기조차 돌아놓으니 사실이지 글자대로 눈이 스르르 내리 감겼다. 김서방과 나는 즉시 잠자리로 향하였다.
  잠자리라니 보들보들한 아름다운 계집이 기다리고 있는 분홍 모기장 속 두툼한 요 위인 줄은 알지 말아라. 그렇다고 어둠침침한 행랑방으로 알라는 것도 아니다. 비록 빈대에는 뜯길망정 어둠침침한 행랑방 하나 나에게는 없었다. 단지 내 몸뚱이 하나인 나는 서울 안을 못 돌아다닐 데 없이 돌아다니면서 노숙露宿을 하였던 것이다. (그래도 그것이 여름이었으니 말이지 겨울이었던들 꼼짝없이 얼어죽었을 것이다.) 따라서 세상에 못 볼~') ||
        TO_CLOB(q'~ 것을 다 보고 겪어 왔었다. 참말이지 별별 야릇하고 말 못할 일이 많았다. 여기에 쓰는 이야기 같은 것은 말하자면 그 중에서 가장 온당한 이야기의 하나에 지나지 못한다.
  어떻든 김서방――도 이미 늦었으니 행랑구석에 가서 빈대에게 뜯기는 것보다는 오히려 노숙하기를 좋아하였다――과 나는 도수장께를 지나서 동묘 앞까지 갔었다.
  어느결엔지 가는 비가 보실보실 뿌리기 시작하였다. 축축한 어둠 속에 칙칙한 동묘가 그 윤곽을 감추고 있었다. 사방은 고요하였다.
  “이 놈들 게 있거라!”
  별안간에 땅에서 솟은 듯이 이런 음성이 들렸다. 나는 깜짝 놀라――는 대신에 빙긋 웃었다.
  “이래 보여두 한여름 동안을 이런 데루 댕기면서 잠자는 놈이다. 그렇게 쉽게 놀래겠니.”
하는 담찬 소리를 남겨 놓고 동묘 대문께로 갔다. 예기한 바와 다름없이 거기에는 벌써 우리 따위의 친구들이 잠자리를 차지하고 있었다. 그래도 꽤 넓은 대문간이지만 그 속에 그득하게 고기새끼 모양으로 오르르 차 있었다. 이리로 눕고 저리로 눕고 허리를 베이고 발치에 코를 박고 드르렁드르렁 코를 골고.
  “이놈들 게 있거라!”
  “아이그 그년……”
  “이런 경칠 자식 보게.”
  엎치락뒤치락 연해연방 잠꼬대소리가 뒤를 이었다. 그러면 이쪽에서는,
  “술맛 좋다!”
하고 입맛을 쩍쩍 다시는 사람도 있었다. 그 바람에 나도 끌려서 어느결에 쩍ᄍᅠᆨ 다시려던 입을 꾹 다물어버리고 나는 어이가 없어 웃으면서 김서방을 둘러보았다.
  “어떡 할려나?”
  “가세!”
