비는 말을 알아듣는 이도 없었다. 그가 아무리 공손히 고개를 돌려도
아버지는 발을 더 세게 구를 뿐이었다. 저쪽에서는 어머니가 쌀쌀한
날씨인데도 창을 활짝 열어젖히고, 몸을 내밀어 창밖 멀리 두 손에
얼굴을 묻었다. 골목과 계단통 사이로 거센 바람이 일어 창의 커튼이
펄럭이고, 식탁 위의 신문들이 바스락거리고, 낱장 몇 장이 바닥 위로
날려 갔다. 아버지는 사정없이 몰아붙이며 야만인처럼 쉿쉿 소리를
냈다. 그러나 그레고르는 뒷걸음질에 아직 전혀 익숙하지 않아서
정말이지 아주 더디게 움직였다. 몸을 돌리기만 해도 된다면 금방 자기
방에 들어갈 수 있었겠지만, 몸을 돌리느라 시간을 끌면 아버지가
짜증을 낼까 두려웠고, 게다가 아버지 손에 든 지팡이가 언제라도 그의
등이나 머리에 치명적인 일격을 내리칠 것만 같았다. 그러나 결국
그레고르에게는 다른 수가 없었다. 뒷걸음질로는 방향조차 제대로 잡지
25
못한다는 것을 깨닫고 소스라쳤기 때문이다. 그래서 그는 쉴 새 없이
겁에 질려 곁눈으로 아버지를 살피면서, 될 수 있는 대로 빨리, 그러나
실제로는 몹시 느릿느릿 몸을 돌리기 시작했다. 어쩌면 아버지는 그의
선의를 알아챘는지, 그가 몸을 돌리는 동안에는 방해하지 않았고 오히려
이따금 멀리서 지팡이 끝으로 그의 회전을 지휘하기까지 했다. 아버지의
저 견딜 수 없는 쉿쉿 소리만 없었더라면! 그 소리에 그레고르는 완전히
넋을 잃었다. 그는 거의 다 돌아섰을 때, 줄곧 그 쉿쉿 소리에 귀를
기울이다가 그만 착각하여 다시 조금 거꾸로 돌기까지 했다. 그러나
마침내 다행히 머리가 문 앞에 닿고 보니, 몸이 너무 넓적해서 그대로는
빠져나갈 수 없었다. 지금 같은 상태의 아버지에게는 물론 다른 쪽
문짝을 열어 그레고르가 지나갈 만한 통로를 터 주자는 생각 따위는
털끝만큼도 떠오르지 않았고, 아버지의 머릿속에는 그레고르가 되도록
빨리 자기 방에 들어가야 한다는 고정관념밖에 없었다. 그레고르가 몸을
일으켜 어쩌면 그렇게 해서 문을 빠져나가는 데 필요한 번거로운 준비도
아버지는 결코 허락하지 않았을 것이다. 어쩌면 아버지는 아무 걸림돌도
없다는 듯 이제 유난히 요란한 소리를 내며 그레고르를 앞으로
몰아댔는지도 몰랐다. 그레고르 뒤에서 나는 소리는 이미 아버지 한
사람의 목소리로는 들리지 않았고, 이제는 정말 장난이 아니어서
그레고르는 무슨 일이 일어나든 될 대로 되라는 심정으로 문틈에 몸을
밀어 넣었다. 몸의 한쪽이 들리면서 그는 문틈에 비스듬히 끼었고, 한쪽
옆구리가 온통 쓸려 벗겨지고, 하얀 문에는 흉한 얼룩이 남았다. 그는 곧
꽉 끼어 혼자서는 더 꼼짝도 할 수 없었고, 한쪽 가는 다리들은 위쪽
허공에 매달려 떨고, 다른 쪽 다리들은 바닥에 짓눌려 아팠다. 그때
아버지가 뒤에서 이제는 정말이지 구원이나 다름없는 힘찬 일격으로
그를 떠밀었고, 그는 피를 몹시 흘리며 멀리 방 안으로 날아 들어갔다.
문이 지팡이로 쾅 닫히고, 마침내 조용해졌다.
26
제2부
그레고르는 해 질 녘이 되어서야 기절한 것처럼 무거운 잠에서
깨어났다. 충분히 쉬고 푹 잤다는 느낌이 들었으니 방해하는 것이
없었더라도 그리 늦지 않게 깨어났을 터였지만, 누군가 서둘러 지나가는
발소리와 현관방으로 난 문을 조심스럽게 닫는 소리에 잠이 깬 것만
같았다. 전차 불빛이 천장과 가구의 윗부분 여기저기에 희미하게 비쳐
있었지만, 아래쪽 그레고르가 있는 곳은 캄캄했다. 그는 이제야 그
쓸모를 알아 가기 시작한 더듬이로 아직 서툴게 앞을 더듬으며, 무슨
일이 있었는지 보려고 문 쪽으로 천천히 몸을 밀고 나아갔다. 왼쪽
옆구리는 기분 나쁘게 당기는 길쭉한 흉터 하나가 된 것 같았고, 그는 두
줄로 난 다리로 그야말로 절뚝거리며 가야 했다. 게다가 다리 하나는
오전의 소동 통에 크게 다쳐서 죽은 듯이 뒤에 질질 끌려 왔다. 하나만
다친 것이 거의 기적이었다.
문 앞에 와서야 그는 무엇이 자기를 그리로 끌어당겼는지 알았다.
먹을 것의 냄새였다. 거기에는 신선한 우유를 가득 채운 사발이 하나
놓여 있었고, 우유에는 흰 빵을 작게 썬 조각들이 떠 있었다. 그는
아침보다 더 배가 고팠으므로 기뻐서 하마터면 웃음을 터뜨릴 뻔했고,
곧바로 눈 위까지 잠길 만큼 머리를 우유 속에 푹 담갔다. 그러나 곧
실망해서 머리를 다시 빼냈다. 성치 않은 왼쪽 옆구리 때문에 먹기가
힘들었을 뿐 아니라(그는 온몸이 씩씩거리며 함께 움직여야만 먹을 수
있었다), 여느 때 같으면 가장 좋아하는 음료여서 누이동생이 틀림없이~') ||
                    TO_CLOB(q'~ 그 때문에 들여놓았을 우유가 전혀 입에 맞지 않았다. 오히려 그는 거의
역겨워하며 사발에서 고개를 돌리고 방 한가운데로 기어 돌아갔다.
문틈으로 보니 거실에는 가스등이 켜져 있었는데, 여느 때 같으면 이
시간에 아버지가 오후에 나오는 신문을 어머니에게, 때로는
누이동생에게도 목소리를 높여 읽어 주곤 했지만 지금은 아무 소리도
들리지 않았다. 하기야 누이동생이 늘 이야기해 주고 편지에도 써
보내던 그 신문 읽기는 요즘 들어 아예 하지 않게 되었는지도 몰랐다.
그러나 집이 틀림없이 비어 있지 않은데도 사방이 그렇게 조용했다.
"우리 식구들은 참 조용히도 사는군." 그레고르는 혼잣말을 하며 꼼짝
않고 어둠 속을 바라보았고, 부모와 누이동생에게 이렇게 좋은 집에서
그런 삶을 누리게 해 줄 수 있었다는 것이 몹시 자랑스러웠다. 그런데
이제 이 모든 평온과 넉넉함과 만족이 끔찍하게 끝나 버린다면 어떻게
될까? 그런 생각에 빠져들지 않으려고 그레고르는 차라리 몸을 움직여
방 안을 이리저리 기어다녔다.
긴 저녁 동안 한 번은 한쪽 옆문이, 한 번은 다른 쪽 옆문이 살짝 틈이
날 만큼 열렸다가 금세 다시 닫혔다. 누군가 들어오고 싶은 마음은
있었지만 망설임도 그만큼 컸던 모양이다. 그레고르는 이제 거실 문
바로 앞에 멈춰 서서, 머뭇거리는 그 방문객을 어떻게든 들어오게
하거나 적어도 그게 누구인지만이라도 알아낼 작정이었다. 그러나 이제
문은 다시 열리지 않았고, 그레고르는 헛되이 기다렸다. 아침에 문이
잠겨 있을 때는 다들 그에게 들어오려 했는데, 이제 그가 문 하나를
열었고 다른 문들도 낮 동안 열린 게 분명한데도 아무도 오지 않았고,
열쇠도 이제는 바깥쪽에 꽂혀 있었다.
밤이 아주 깊어서야 거실 불이 꺼졌는데, 셋이 이제 모두 발끝으로
걸어 멀어지는 소리가 똑똑히 들렸으니 부모와 누이동생이 그때까지
깨어 있었다는 것을 쉽게 알 수 있었다. 이제 아침까지는 틀림없이
28
아무도 그레고르에게 들어오지 않을 터였다. 그러니 그는 앞으로 삶을
어떻게 새로 꾸려야 할지 방해받지 않고 궁리할 시간이 넉넉했다.
그러나 바닥에 납작 엎드려 있어야만 하는 이 천장 높고 휑한 방이 그는
왠지 무서웠고, 그 까닭은 알아낼 수 없었다. 다섯 해 동안 자기가
살아온 방이었으니까. 그리고 그는 반쯤은 자기도 모르게 몸을 돌려,
약간 부끄러워하면서 소파 밑으로 서둘러 들어갔다. 거기서는 등이 조금
눌리고 머리를 더는 들 수 없었는데도 금세 아주 아늑했고, 다만 몸이
너무 넓적해서 소파 밑에 다 들어가지 않는 것이 아쉬울 뿐이었다.
그는 거기서 밤을 꼬박 새웠는데, 밤의 일부는 허기 때문에 자꾸
소스라쳐 깨는 선잠 속에서, 일부는 걱정과 막연한 희망 속에서 보냈다.
그러나 걱정도 희망도 모두 같은 결론에 이르렀다. 당분간은 조용히
지내면서, 지금 같은 상태로는 어차피 가족에게 끼칠 수밖에 없는
불편을 인내와 더없는 배려로 가족이 견딜 만하게 해 주어야 한다는
결론이었다.
이른 아침, 아직 밤이나 다름없을 때 벌써 그레고르는 방금 내린
결심이 얼마나 굳은지 시험해 볼 기회를 얻었다. 누이동생이 옷을 거의
다 입은 차림으로 현관방 쪽에서 문을 열고 잔뜩 긴장한 채 안을
들여다보았기 때문이다. 누이동생은 그를 바로 찾지 못했지만, 소파
밑에 있는 그를 알아보자(맙소사, 그는 어딘가에 있을 수밖에 없었다.
날아가 버렸을 리는 없지 않은가) 너무 놀란 나머지 스스로를 억누르지
못하고 밖에서 문을 도로 쾅 닫아 버렸다. 그러나 자기가 한 짓을
뉘우치기라도 하듯 곧바로 다시 문을 열고, 중환자나 아예 낯선 사람의
방에라도 들어가듯 발끝으로 걸어 들어왔다. 그레고르는 머리를 소파
가장자리 바로 앞까지 내밀고 누이동생을 지켜보았다. 누이동생은 그가
우유를 그대로 남겨 둔 것을, 그것도 결코 배가 고프지 않아서가
아니라는 것을 알아챌까, 그리고 그에게 더 잘 맞는 다른 음식을
29
들여올까? 누이동생이 스스로 그러지 않는다면 그는 그것을 일깨워
주느니 차라리 굶어 죽을 생각이었다. 사실은 소파 밑에서 튀어나가
누이동생 발치에 몸을 던지고 무엇이든 맛있는 먹을 것을 달라고 빌고
싶은 마음이 엄청나게 북받쳤는데도 그랬다. 그러나 누이동생은 둘레에
우유가 조금 엎질러졌을 뿐 아직 가득한 사발을 보고 곧 놀라워하더니,
맨손이 아니라 헝겊 조각으로 그것을 바로 집어 들어 내갔다.
그레고르는 누이동생이 그 대신 무엇을 가져올지 몹시 궁금해서
이런저런 생각을 다 해 보았다. 그러나 누이동생이 착한 마음으로
실제로 한 일은 그로서는 결코 짐작할 수 없었을 것이다. 누이동생은
그의 입맛을 알아보려고 갖가지 먹을 것을 골고루 헌 신문지 위에 펼쳐
가져왔다. 반쯤 썩은 묵은 채소가 있었고, 저녁 식사 때 남은 뼈다귀에는
하얀 소스가 굳어 엉겨 붙어 있었고, 건포도와 아몬드가 몇 알,
그레고르가 이틀 전에 못 먹겠다고 선언한 치즈 한 덩이, 마른 빵 한
조각, 버터 바른 빵 한 조각, 버터를 바르고 소금을 친 빵 한 조각이
있었다. 그 밖에도 누이동생은 이 모든 것 곁에, 아마 아예 그레고르
몫으로 정해 둔 듯한 그 사발에 물을 부어 놓아두었다. 그리고
그레고르가 자기 앞에서는 먹지 않으리라는 것을 알았으므로, 섬세한
마음씨로 서둘러 자리를 비켜 주고 열쇠까지 돌려 잠갔다. 그레고르가
마음껏 편하게 굴어도 된다는 것을 알아차리게 하려는 배려였다. 이제
먹을 차례가 되자 그레고르의 가는 다리들이 바르르 떨렸다. 게다가
상처도 이미 다 나은 게 틀림없었다. 그는 더는 거북한 데를 느끼지
않았고, 그게 놀라워서, 한 달도 더 전에 칼에 손가락을 아주 조금
베었는데 그 상처가 그저께까지도 꽤 아팠던 것을 떠올렸다. "이제는
내가 덜 예민해진 걸까?" 그는 생각하며 벌써 치즈를 게걸스럽게 빨았다.
다른 어떤 음식보다 먼저 대번에 그를 세차게 끌어당긴 치즈였다. 그는
만족스러워 눈물까지 글썽이며 치즈와 채소와 소스를 잇달아 재빨리
30
먹어 치웠다. 반면 신선한 음식은 입에 맞지 않았고 그 냄새조차 견딜 수
없어서, 먹고 싶은 것들을 거기서 조금 떨어진 곳으로 끌고 가기까지
했다. 그가 벌써 다 먹고 그 자리에 그저 늘어져 누워 있을 때,
누이동생이 물러나라는 신호로 천천히 열쇠를 돌렸다. 그는 거의
잠들려던 참이었지만 그 소리에 화들짝 놀라 다시 소파 밑으로 서둘러
들어갔다. 그러나 누이동생이 방에 있는 잠깐 동안만이라도 소파 밑에
