파출부가 여전히 갈 생각을 하지 않자 그제야 짜증스럽게 고개를
들었다. "뭐요?" 잠자 씨가 물었다. 파출부는 가족에게 큰 경사를 알려 줄
게 있는데 꼬치꼬치 물어봐야만 알려 주겠다는 듯 웃으며 문간에 서
있었다. 모자에 거의 꼿꼿이 꽂힌 작은 타조 깃털이 사방으로 살랑살랑
흔들렸다. 잠자 씨는 파출부가 일하러 온 뒤로 줄곧 그 깃털이 거슬렸다.
"그래, 대체 뭘 원하는 거예요?" 잠자 부인이 물었다. 파출부가 그래도
가장 어려워하는 사람이 잠자 부인이었다. "네." 파출부는 대답하고는
상냥하게 웃느라 곧바로 말을 잇지 못했다. "그러니까 옆방 그것을
어떻게 치울지는 걱정하실 것 없어요. 다 처리됐어요." 잠자 부인과
그레테는 계속 쓰려는 듯 편지 위로 몸을 숙였다. 잠자 씨는 파출부가
이제 모든 것을 자세히 늘어놓기 시작하려 한다는 것을 알아채고 손을
내밀어 단호하게 막았다. 이야기를 할 수 없게 되자 파출부는 자기가
몹시 바쁘다는 것을 떠올리고, 분명히 기분이 상해서 "그럼 다들
안녕히!" 하고 외치더니, 홱 돌아서서 문을 무시무시하게 쾅 닫고 집을
나갔다.
"저녁에 내보내야겠군." 잠자 씨가 말했지만, 아내에게서도
딸에게서도 아무 대답이 없었다. 파출부가 겨우 얻은 두 사람의 평온을
다시 흐트러뜨린 듯했다. 두 사람은 일어나 창가로 가서 서로 끌어안은
채 거기 서 있었다. 잠자 씨는 자기 의자에 앉은 채 몸을 돌려 한동안
말없이 두 사람을 바라보았다. 그러다가 외쳤다. "자, 이리들 와라. 이제
지나간 일은 그만 좀 놓아 버려. 그리고 나도 좀 배려해 주고." 두 여자는
곧 그의 말을 따라 그에게 달려가서 그를 어루만지고는 편지를 서둘러
끝냈다.
그러고 나서 셋은 함께 집을 나섰다. 벌써 몇 달 동안 하지 않았던
일이었다. 그들은 전차를 타고 시내를 벗어나 교외로 나갔다. 그들만
타고 있는 전차 칸에는 따스한 햇살이 가득 비쳐 들었다. 그들은 좌석에
65
편히 등을 기대고 앉아 앞날의 전망을 이야기했고, 찬찬히 따져 보니
앞날이 결코 나쁘지 않다는 것을 알게 되었다. 서로 아직 제대로 물어본
적도 없었지만 셋의 일자리가 모두 아주 괜찮았고 특히 앞으로 무척
유망했기 때문이다. 지금 형편을 가장 크게 낫게 하는 일은 물론 이사로
쉽게 이룰 수 있을 터였다. 그들은 이제 그레고르가 고른 지금 집보다
작고 값싸지만 자리가 더 좋고 여러모로 더 실용적인 집을 얻으려 했다.
그렇게 이야기를 나누는 동안, 잠자 씨와 잠자 부인은 점점 더 생기를
띠는 딸을 보며, 요즘 온갖 돌봄으로 뺨이 창백해졌는데도 딸이 어느새
예쁘고 풍만한 처녀로 활짝 피어났다는 것을 거의 동시에 깨달았다. 두
사람은 차츰 말이 없어지면서 거의 무심결에 눈길로 뜻을 주고받으며,
이제 딸에게 착실한 신랑감을 찾아 줄 때가 되었다고 생각했다. 그리고
목적지에 이르러 딸이 맨 먼저 일어나 젊은 몸을 쭉 폈을 때, 그들에게는
그것이 자기들의 새로운 꿈과 좋은 뜻을 확인해 주는 것처럼 여겨졌다.~')
WHERE b_title = '변신'
  AND b_author = '프란츠 카피카';







