따르라는 분부를 받았습니다."
"나는 하이드 씨를 만난 적이 없는 것 같은데?" 어터슨이 물었다.
"아이고, 아닙니다, 나리. 그분은 여기서 식사를 하신 적이 없습니다."
집사가 대답했다. "사실 집 이쪽에서는 그분을 거의 뵙지 못합니다.
그분은 대개 실험실로 드나드십니다."
"그럼, 잘 자게, 풀."
"안녕히 주무십시오, 어터슨 나리."
그리고 변호사는 몹시 무거운 마음으로 집으로 향했다. '가엾은 해리
지킬,' 그는 생각했다. '아무래도 깊은 물에 빠진 것 같아 마음이 놓이지
않는군! 젊을 때 방탕했지. 물론 아주 오래전 일이지만, 하느님의 법에는
시효라는 게 없어. 그래, 틀림없이 그거야. 해묵은 죄의 유령, 감춰 둔
망신의 암 덩어리. 기억은 오래전에 잊고 자기애는 잘못을 눈감아 준
뒤에야, 여러 해 뒤에야 벌이 절름거리는 발로(pede claudo) 찾아오는
거지.' 변호사는 그 생각에 겁이 나서 한동안 자기 과거를 곱씹으며, 행여
해묵은 죄 하나가 뚜껑을 열면 튀어나오는 인형처럼 거기서 불쑥 빛
26
속으로 튀어나오지나 않을까 하고 기억의 구석구석을 더듬었다. 그의
과거는 꽤 흠잡을 데 없어서, 자기 삶의 기록을 그보다 덜 불안하게 읽을
수 있는 사람은 드물었다. 그런데도 그는 자기가 저지른 숱한 나쁜 일을
떠올리며 먼지 속까지 낮아졌고, 하마터면 저지를 뻔했지만 피해 간
숱한 일을 떠올리며 다시 차분하고 두려운 감사 속으로 일으켜
세워졌다. 그러다 앞의 문제로 다시 돌아가자, 그는 희망의 불꽃 하나를
품게 되었다. '이 하이드 군을 잘 캐 보면,' 그는 생각했다. '그자한테도
틀림없이 제 비밀이 있을 거야. 생긴 꼴로 보아 시커먼 비밀이겠지.
가엾은 지킬의 가장 나쁜 비밀도 그에 비하면 햇빛 같을 그런 비밀
말이야. 이대로 갈 수는 없어. 그런 작자가 도둑처럼 해리의 침대
머리맡으로 숨어드는 걸 생각하면 소름이 끼쳐. 가엾은 해리, 얼마나
끔찍한 깨어남인가! 게다가 위험하기도 하지, 이 하이드라는 자가
유언장이 있다는 걸 눈치채면, 물려받고 싶어 몸이 달지도 모르니까.
그래, 내가 어깨를 걸고 나서야 해. 지킬이 허락만 해 준다면.' 그는
덧붙였다. '지킬이 허락만 해 준다면.' 그의 마음의 눈앞에 다시 한번
유언장의 그 이상한 조항들이 환등 그림처럼 또렷이 떠올랐던 것이다.
제3장 지킬 박사는 아주 태연했다
두 주 뒤, 참으로 운 좋게도 박사가 오랜 벗 대여섯을 불러 그 기분 좋은
만찬을 한 차례 베풀었는데, 모두 지성 있고 평판 좋은 사람들이자 좋은
포도주를 가릴 줄 아는 이들이었고, 어터슨 씨는 다른 손님들이 떠난
뒤에도 자기만 남아 있도록 일을 꾸몄다. 새삼스러운 일이 아니라 이미
수십 번도 넘게 있었던 일이었다. 어터슨을 좋아하는 사람들은 그를
아주 좋아했다. 마음 가볍고 입 가벼운 이들이 벌써 문턱에 발을
올려놓을 때면, 주인들은 이 무뚝뚝한 변호사를 붙잡아 두기를
좋아했고, 떠들썩하게 즐기느라 힘을 쓰고 애를 쓴 뒤에는 나서지 않는
그의 곁에 잠시 앉아 혼자 있을 때를 미리 익히고, 그 사람의 넉넉한
침묵 속에서 마음을 가라앉히기를 좋아했다. 지킬 박사도 이 규칙에서
벗어나지 않았다. 이제 난롯불 맞은편에 앉은 그는 크고 잘생긴, 매끈한
얼굴의 쉰 살 남자로, 어쩌면 멋을 부리는 기색이 조금 있었지만 능력과
다정함의 표지를 빠짐없이 지니고 있었는데, 그의 얼굴만 보아도 그가
어터슨 씨에게 진심 어린 따뜻한 애정을 품고 있다는 것을 알 수 있었다.
"자네하고 이야기를 좀 하고 싶었네, 지킬." 어터슨이 먼저 입을
열었다. "자네 그 유언장 알지?"
눈여겨보는 사람이라면 그 화제가 달갑지 않다는 것을 눈치챘을지도
모른다. 그러나 박사는 쾌활하게 넘겼다. "가엾은 어터슨," 그가 말했다.
"자네는 이런 의뢰인을 만나서 참 운이 없구먼. 자네가 내 유언장 때문에
괴로워하는 것만큼 괴로워하는 사람은 본 적이 없어, 래니언, 그
28
고리타분한 꽁생원이 내 과학적 이단이라는 것 때문에 괴로워하는 걸
빼면 말일세. 아, 그 친구가 좋은 사람이라는 건 아네. 얼굴 찌푸릴 것
없어. 훌륭한 친구고 언제나 좀 더 자주 만나야지 생각하고 있지만,
그래도 고리타분한 꽁생원인 건 어쩔 수 없어, 무식하고 시끄러운
꽁생원이지. 나는 래니언만큼 실망스러운 사람을 본 적이 없네."
"내가 그걸 한 번도 찬성한 적이 없다는 건 자네도 알지." 어터슨은
새로 꺼낸 화제를 사정없이 무시하고 말을 이었다.
"내 유언장 말인가? 그래, 물론 알지." 박사가 조금 날카롭게 말했다.
"자네가 그렇게 말했으니까."
"그래, 다시 한번 말하겠네." 변호사가 말을 이었다. "젊은 하이드에
대해 좀 알게 된 게 있어서 말일세."
지킬 박사의 크고 잘생긴 얼굴이 입술까지 하얗게 질리고, 눈가에
검은 그늘이 졌다. "더 듣고 싶지 않네." 그가 말했다. "그 일은 그만 덮어
두기로 우리가 합의한 줄 알았는데."
"내가 들은 건 끔찍한 일이었네." 어터슨이 말했다.
"그래 봤자 달라질 건 없어. 자네는 내 처지를 몰라." 박사가 어딘가
앞뒤가 맞지 않는 태도로 대꾸했다. "나는 괴로운 처지에 놓여 있네,
어터슨. 내 처지는 아주 이상해. 아주 이상한 처지란 말일세. 말로 해서
고칠 수 있는 그런 일이 아니야."
"지킬," 어터슨이 말했다. "자네는 나를 알지. 나는 믿어도 되는
사람이야. 비밀은 지킬 테니 숨김없이 털어놓게. 틀림없이 내가 자네를
거기서 빼내 줄 수 있을 걸세."
"어터슨, 이 사람아," 박사가 말했다. "참 고마운 말일세. 정말이지
고마운 말이야. 무슨 말로 고맙다고 해야 할지 모르겠군. 나는 자네를
온전히 믿고, 고를 수만 있다면 살아 있는 어느 누구보다도, 그래, 나
자신보다도 자네를 먼저 믿을 걸세. 하지만 정말이지 자네가 생각하는~') ||
