어터슨은 난롯불을 바라보며 잠시 생각에 잠겼다.
"자네 말이 전적으로 옳겠지." 마침내 그가 자리에서 일어나며 말했다.
"그래, 그런데 이 일을 꺼낸 김에, 그리고 이번이 마지막이기를
