30
제4장 커루 살인 사건
거의 한 해가 지난 18…년 10월, 런던은 유난히 잔혹한 데다 피해자의
지위가 높아 더욱 세상의 눈길을 끈 범죄 하나로 발칵 뒤집혔다. 알려진
사실은 몇 가지 되지 않았지만 하나같이 놀라웠다. 강에서 멀지 않은
어느 집에 혼자 살던 하녀가 열한 시쯤 잠자리에 들려고 위층으로
올라갔다. 새벽녘에는 안개가 도시를 덮었지만 초저녁에는 하늘에 구름
한 점 없었고, 하녀의 창문이 내려다보는 골목은 보름달 빛에 환히
밝았다. 하녀는 낭만을 즐기는 성미였던 모양으로, 창문 바로 아래 놓인
제 상자에 걸터앉아 꿈결 같은 상념에 잠겼다. 그때만큼(나중에 그 일을
이야기할 때면 하녀는 눈물을 줄줄 흘리며 늘 이렇게 말했다) 그때만큼
모든 사람과 평화롭다고 느낀 적도, 세상을 너그럽게 여긴 적도
없었다는 것이다. 그렇게 앉아 있는데, 머리가 하얗게 센 아름다운
노신사 한 사람이 골목을 따라 다가오는 것이 보였고, 그를 맞이하듯
마주 오는 또 한 사람, 몸집이 아주 작은 신사도 있었는데, 처음에
하녀는 그쪽에는 별로 눈길을 주지 않았다. 두 사람이 말이 들릴 만한
거리까지 가까워지자(바로 하녀의 눈 아래였다), 나이 든 사람이 고개
숙여 인사하고 무척 고상하고 예의 바른 몸짓으로 상대에게 말을
걸었다. 그가 건네는 이야기가 대단히 중요한 내용 같지는 않았고,
오히려 손으로 가리키는 것을 보면 때로는 그저 길을 묻는 것 같기도
했다. 그러나 그가 말하는 동안 달빛이 그의 얼굴을 비추었고, 하녀는 그
얼굴을 바라보는 것이 즐거웠는데, 그 얼굴에서는 순진하고 옛 시절다운
31
다정한 성품이 숨 쉬는 것 같았고, 그러면서도 마땅한 근거가 있는
자족감 같은 높은 기품도 느껴졌다. 이윽고 하녀의 눈길이 다른
사람에게로 옮겨 갔는데, 놀랍게도 그는 하녀가 아는 하이드 씨라는
사람이었다. 한때 하녀의 주인을 찾아온 적이 있는 사람으로, 하녀는
그때 그를 싫어하게 되었다. 그는 손에 묵직한 지팡이를 들고
만지작거리고 있었지만, 한마디도 대꾸하지 않았고, 참을성 없는 기색을
제대로 감추지도 못한 채 듣고 있는 것 같았다. 그러다 느닷없이 그는
분노로 활활 타오르며 발을 구르고 지팡이를 휘두르며 (하녀의
표현으로는) 미치광이처럼 날뛰었다. 노신사는 몹시 놀라고 조금 마음이
상한 듯한 얼굴로 한 걸음 물러섰고, 그러자 하이드 씨는 아예 고삐가
풀려, 지팡이로 그를 내리쳐 땅바닥에 쓰러뜨렸다. 그리고 다음 순간,
원숭이 같은 광포함으로 피해자를 발로 짓밟으며 우박처럼 매질을
퍼부었는데, 그 매질에 뼈가 부서지는 소리가 똑똑히 들렸고 몸뚱이가
길바닥에서 튀어 올랐다. 그 끔찍한 광경과 소리에 하녀는 정신을
잃었다.
하녀가 정신을 차리고 경찰을 부른 것은 두 시였다. 살인자는
오래전에 사라지고 없었지만, 피해자는 믿을 수 없을 만큼 처참하게
망가진 채 골목 한가운데 쓰러져 있었다. 흉기로 쓰인 지팡이는 드물고
아주 단단하고 무거운 나무로 만든 것이었는데도, 이 분별없는 잔혹함을
견디지 못하고 한가운데가 부러져 있었고, 쪼개진 반쪽은 옆 도랑으로
굴러가 있었고, 나머지 반쪽은 틀림없이 살인자가 가지고 갔을 것이다.
피해자의 몸에서는 지갑과 금시계가 나왔지만, 명함이나 서류는 하나도
없었고, 봉인하고 우표를 붙인 봉투 한 통만 있었다. 아마 우체통에
넣으러 가던 길이었을 그 봉투에는 어터슨 씨의 이름과 주소가 적혀
있었다.
32
봉투는 이튿날 아침 변호사가 잠자리에서 일어나기도 전에 그에게
전해졌다. 그는 그것을 보고 사정을 듣자마자 엄숙하게 입술을
내밀었다. "시신을 보기 전에는 아무 말도 하지 않겠소." 그가 말했다.
