한 주 뒤 래니언 박사는 자리에 누웠고, 두 주가 채 안 되어 세상을
떠났다. 장례식에서 몹시 슬픔에 잠겼던 어터슨은 장례식 다음 날 밤
일하는 방의 문을 잠그고, 쓸쓸한 촛불 아래 앉아 죽은 친구의 손으로
주소를 쓰고 그의 인장으로 봉한 봉투 하나를 꺼내 앞에 놓았다. "친전.
G. J. 어터슨 한 사람만 열어 볼 것. 그가 먼저 세상을 떠났을 경우에는
읽지 말고 없앨 것." 봉투 겉에는 이렇게 힘주어 쓰여 있었고, 변호사는
그 내용을 보기가 두려웠다. '오늘 친구 하나를 묻었는데,' 그는
생각했다. '이것 때문에 또 하나를 잃게 되면 어쩌나?' 그러다 그는 그런
두려움은 신의를 저버리는 것이라고 스스로 꾸짖고 봉인을 뜯었다.
안에는 또 하나의 봉투가 들어 있었는데, 그것도 봉해져 있었고, 겉에
「헨리 지킬 박사가 죽거나 실종되기 전에는 열지 말 것」이라고 적혀
있었다. 어터슨은 자기 눈을 믿을 수 없었다. 그렇다, 실종이었다.
오래전에 그 주인에게 돌려준 그 미친 유언장에서처럼, 여기서 또다시
실종이라는 생각과 헨리 지킬이라는 이름이 한데 묶여 있었다. 그러나
유언장에서 그 생각은 하이드라는 사내의 불길한 귀띔에서 나와, 너무도
뻔하고 끔찍한 목적으로 거기 들어가 있었다. 그런데 래니언의 손으로
쓰인 이 말은 무슨 뜻일까? 금지 따위는 무시하고 당장 이 수수께끼들의
밑바닥까지 뛰어들고 싶은 엄청난 호기심이 수탁자의 가슴에
46
밀려들었다. 그러나 직업상의 명예와 죽은 친구에 대한 신의는 엄격한
의무였고, 그 꾸러미는 그의 개인 금고 가장 깊숙한 구석에서 잠들었다.
호기심을 누르는 것과 호기심을 이기는 것은 서로 다른 일이어서,
그날부터 어터슨이 살아남은 친구와 어울리기를 예전처럼 간절히
바랐는지는 의심스럽다. 그는 그 친구를 다정하게 생각했지만, 그
생각은 불안하고 두려웠다. 그는 실제로 찾아가기는 했지만, 어쩌면
들여보내 주지 않아 마음이 놓였는지도 모른다. 스스로 택한 속박의
집에 들어가 그 속을 알 수 없는 은둔자와 앉아 이야기하기보다는, 문간
계단에 서서 탁 트인 도시의 공기와 소리에 둘러싸여 풀과 이야기하는
편을 어쩌면 속으로 더 좋아했는지도 모른다. 사실 풀이 전해 줄 소식도
그리 즐거운 것이 아니었다. 박사는 이제 어느 때보다도 실험실 위
서재에 틀어박혀 지내며, 때로는 거기서 잠까지 자는 듯했다. 기운이
없고, 몹시 말이 없어졌으며, 책도 읽지 않아서, 무언가 마음에 걸리는
일이 있는 것 같았다. 어터슨은 늘 똑같은 이런 소식에 아주 익숙해져서,
조금씩 찾아가는 횟수를 줄여 갔다.
