제8장 마지막 밤
어느 날 저녁 식사를 마친 어터슨 씨가 난롯가에 앉아 있는데, 뜻밖에도
풀이 찾아왔다.
"아니, 풀, 웬일인가?" 그가 외쳤다. 그러다 그를 다시 한번
쳐다보고는 덧붙였다. "무슨 일이 있나? 박사가 아픈가?"
"어터슨 나리," 사내가 말했다. "뭔가 잘못되었습니다."
"앉게, 여기 포도주도 한 잔 있네." 변호사가 말했다. "자, 천천히,
원하는 게 뭔지 똑똑히 말해 보게."
"나리도 박사님 버릇은 아시지요." 풀이 대답했다. "그렇게
틀어박히시는 것 말입니다. 그런데 이번에도 서재에 틀어박히셨는데,
저는 그게 마음에 들지 않습니다, 나리. 마음에 든다면 벼락을 맞아도
좋습니다. 어터슨 나리, 저는 무섭습니다."
"이 사람아," 변호사가 말했다. "분명하게 말해 보게. 무엇이 무섭다는
건가?"
"한 주쯤 전부터 무서웠습니다." 풀은 물음을 고집스럽게 못 들은
척하며 대꾸했다. "이제는 더 견딜 수가 없습니다."
사내의 모습이 그 말을 넉넉히 뒷받침해서, 그의 태도는 나쁜 쪽으로
달라져 있었고 처음 무섭다고 털어놓던 순간 말고는 한 번도 변호사의
얼굴을 똑바로 보지 않았다. 지금도 그는 입도 대지 않은 포도주 잔을
무릎에 올려놓은 채 방바닥 한구석에 눈길을 두고 앉아 있었다. "이제는
더 견딜 수가 없습니다." 그가 되풀이했다.
51
"자," 변호사가 말했다. "자네한테 그럴 만한 까닭이 있다는 건
알겠네, 풀. 무언가 심각하게 잘못되었다는 것도 알겠어. 그게 무엇인지
말해 보게."
"흉한 일이 벌어진 것 같습니다." 풀이 쉰 목소리로 말했다.
"흉한 일이라니!" 꽤 겁이 나서 그 때문에 조금 짜증이 나려던
변호사가 외쳤다. "무슨 흉한 일! 이 사람이 무슨 소리를 하는 건가?"
"감히 말씀드릴 수가 없습니다, 나리." 대답이 돌아왔다. "저와 함께
가셔서 직접 보시겠습니까?"
어터슨 씨는 대답 대신 일어나 모자와 두꺼운 외투를 챙겼지만,
그러면서 집사의 얼굴에 떠오른 크나큰 안도의 빛을 보고 놀랐고, 그에
못지않게, 뒤따라 나서려고 잔을 내려놓을 때까지도 포도주에 입도 대지
않았다는 것에도 놀랐는지 모른다.
바람에 기울어진 듯 하얗게 바랜 달이 등을 대고 누워 있고 더없이
투명하고 얇은 천 같은 조각구름이 날아가는, 거칠고 추운 3월다운
밤이었다. 바람 때문에 말을 하기 어려웠고, 얼굴에는 피가 몰려 붉은
얼룩이 졌다. 게다가 바람이 거리를 유난히 말끔히 쓸어 낸 듯 행인이
없어서, 어터슨 씨는 런던의 그 동네가 이렇게 텅 빈 것은 처음 보는 것
같았다. 차라리 그렇지 않기를 바랐다. 평생 처음으로 그는 다른
사람들을 보고 만지고 싶다는 바람을 이토록 날카롭게 느꼈는데, 아무리
애써도 재앙이 닥치리라는 짓누르는 예감이 마음속으로 밀려들었기
때문이다. 그들이 이른 광장은 바람과 먼지로 가득했고, 가운데 뜰의
가냘픈 나무들은 쇠울타리에 제 몸을 채찍질하듯 부딪치고 있었다. 오는
내내 한두 걸음 앞서 걷던 풀은 이제 보도 한가운데서 걸음을 멈추고,
살을 에는 날씨인데도 모자를 벗더니 붉은 손수건으로 이마를 닦았다.
그러나 서둘러 오기는 했어도 그가 닦아 낸 것은 힘을 써서 맺힌 땀이
52
아니라, 숨통을 조이는 어떤 고뇌가 짜낸 진땀이었으니, 그의 얼굴은
