집사는 칼 닦는 아이에게 말을 이었다. "촛불 하나 갖다 다오. 당장 이
일을 끝장내야겠다." 그런 다음 그는 어터슨 씨에게 따라와 달라고
청하고 앞장서서 뒤뜰로 나갔다.
53
"자, 나리," 그가 말했다. "되도록 살그머니 오십시오. 나리께서
