제10장 헨리 지킬의 사건 전말 진술
나는 18…년에 큰 재산을 물려받을 몸으로 태어났고, 게다가 뛰어난
재능을 타고났으며, 천성이 부지런하고 동료 인간들 가운데 지혜롭고
