차지한 자리를 헤아려 보기 시작했을 때, 나는 이미 깊이 갈라진 이중의
삶에 몸을 던진 뒤였다. 내가 저지른 것과 같은 탈선이라면 오히려
떠벌리고 다녔을 사람도 많았을 것이다. 그러나 나는 내 앞에 세워 둔
높은 이상 때문에 거의 병적인 수치심으로 그것을 바라보고 감추었다.
그러니 나를 그런 사람으로 만든 것은 내 결점이 유난히
타락해서라기보다 내 포부가 그토록 까다로웠기 때문이었고, 그 포부가
