75
나는 결코 위선자가 아니었다. 내 두 쪽은 모두 죽을 만큼 진지했다.
자제를 벗어던지고 수치 속으로 뛰어들 때의 나도, 대낮에 사람들의
눈앞에서 지식을 넓히거나 슬픔과 고통을 덜어 주려고 애쓸 때의 나와
조금도 다르지 않은 나 자신이었다. 그런데 공교롭게도 오로지 신비롭고
