그리고 일찍부터, 내 과학적 발견이 그런 기적의 맨 가능성조차
내비치기 시작하기도 전부터, 나는 이 요소들을 갈라놓는다는 생각에
사랑하는 백일몽처럼 즐겨 잠기곤 했다. 나는 스스로에게 말하곤 했다.
